import{_ as e,o as r,c as t,ae as o}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"考拉记账用户协议","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/terms.md","filePath":"zh-HK/terms.md"}'),n={name:"zh-HK/terms.md"};function p(s,a,h,l,i,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="考拉记账用户协议" tabindex="-1"><strong>考拉记账</strong>用户协议 <a class="header-anchor" href="#考拉记账用户协议" aria-label="Permalink to &quot;**考拉记账**用户协议&quot;">​</a></h1><p>更新日期：2026 年 04 月 24 日</p><p>生效日期：2026 年 04 月 24 日</p><p>本《考拉记账用户协议》（以下简称“本协议”）由【应用运营主体名称】及其关联方（以下简称“我们”）与使用 Koala（以下简称“本应用”）的用户（以下简称“你”）共同缔结。</p><p>在你开始使用本应用之前，请你务必审慎阅读并充分理解本协议各条款内容。你点击“同意/接受”或以任何方式实际使用本应用服务，即表示你已阅读并同意接受本协议的约束。</p><h2 id="_1-定义" tabindex="-1"><strong>1. 定义</strong> <a class="header-anchor" href="#_1-定义" aria-label="Permalink to &quot;**1. 定义**&quot;">​</a></h2><p>​ 1. 本应用：指 Koala 客户端软件及其相关服务。</p><p>​ 2. 服务：指我们基于本应用向你提供的记账、数据管理、导入导出、云同步（如有）、会员（如有）等功能与技术服务。</p><p>​ 3. 账号：指你用于登录本应用服务的身份标识（如 Apple 账号登录）。</p><h2 id="_2-协议的范围与变更" tabindex="-1"><strong>2. 协议的范围与变更</strong> <a class="header-anchor" href="#_2-协议的范围与变更" aria-label="Permalink to &quot;**2. 协议的范围与变更**&quot;">​</a></h2><p>​ 1. 本协议内容包括本协议正文以及我们已经发布或将来可能发布的与本应用相关的各类规则、公告、说明等。前述内容一经正式发布，均为本协议不可分割的组成部分。</p><p>​ 2. 我们有权在必要时修改本协议条款，并在本应用内或相关页面进行提示。若你在修改后继续使用本服务，即表示你已接受修改后的协议；若你不接受修改后的协议，你应停止使用本服务。</p><h2 id="_3-账号与使用规则" tabindex="-1"><strong>3. 账号与使用规则</strong> <a class="header-anchor" href="#_3-账号与使用规则" aria-label="Permalink to &quot;**3. 账号与使用规则**&quot;">​</a></h2><p>​ 1. 你应当遵守法律法规及本协议约定使用本服务，不得利用本服务从事任何违法违规活动。</p><p>​ 2. 你应妥善保管你的登录凭据与设备，因你自身原因导致的账号被盗用或数据泄露风险，由你自行承担相应责任。</p><p>​ 3. 若你通过第三方账号（如 Apple）登录，我们会按第三方平台规则进行必要的授权与验证。</p><h2 id="_4-服务内容与使用限制" tabindex="-1"><strong>4. 服务内容与使用限制</strong> <a class="header-anchor" href="#_4-服务内容与使用限制" aria-label="Permalink to &quot;**4. 服务内容与使用限制**&quot;">​</a></h2><p>​ 1. 本服务以“现状”形式提供。我们会努力保障服务稳定，但不承诺服务不会中断或没有错误。</p><p>​ 2. 你理解并同意：我们可能基于产品迭代、运营策略或合规要求，对服务内容进行调整或停止部分功能，并在合理范围内进行提示。</p><p>​ 3. 若你拒绝同意必要的协议或隐私政策，可能导致你无法使用本应用的核心功能或无法继续使用本服务。</p><h2 id="_5-付费服务-如有" tabindex="-1"><strong>5. 付费服务（如有）</strong> <a class="header-anchor" href="#_5-付费服务-如有" aria-label="Permalink to &quot;**5. 付费服务（如有）**&quot;">​</a></h2><p>​ 1. 本应用可能提供订阅/内购等付费服务（如会员权益）。具体内容、价格、周期、自动续费规则以购买页面展示及相关说明为准。</p><p>​ 2. 你理解并同意：支付、退订、退款等规则可能受 Apple App Store 等第三方平台规则约束。</p><h2 id="_6-知识产权" tabindex="-1"><strong>6. 知识产权</strong> <a class="header-anchor" href="#_6-知识产权" aria-label="Permalink to &quot;**6. 知识产权**&quot;">​</a></h2><p>​ 1. 本应用及其相关内容（包括但不限于页面设计、图标、文本、程序代码等）的知识产权归我们或相关权利人所有。</p><p>​ 2. 未经我们书面许可，你不得以任何形式复制、修改、传播、反向工程本应用或其内容。</p><h2 id="_7-免责声明与责任限制" tabindex="-1"><strong>7. 免责声明与责任限制</strong> <a class="header-anchor" href="#_7-免责声明与责任限制" aria-label="Permalink to &quot;**7. 免责声明与责任限制**&quot;">​</a></h2><p>​ 1. 因不可抗力、第三方原因、网络环境、设备故障等导致服务不可用或数据异常的，我们在法律允许范围内不承担由此产生的损失。</p><p>​ 2. 你理解记账数据、导入导出文件等由你自行维护备份。若你未进行备份而造成数据丢失，我们在法律允许范围内不承担责任。</p><h2 id="_8-个人信息保护" tabindex="-1"><strong>8. 个人信息保护</strong> <a class="header-anchor" href="#_8-个人信息保护" aria-label="Permalink to &quot;**8. 个人信息保护**&quot;">​</a></h2><p>​ 1. 我们非常重视你的个人信息保护。你在使用本服务时，我们将按照《Koala 隐私政策》处理你的个人信息。</p><p>​ 2. 《考拉记账隐私政策》是本协议的重要组成部分，与本协议具有同等法律效力。</p><h2 id="_9-适用法律与争议解决" tabindex="-1"><strong>9. 适用法律与争议解决</strong> <a class="header-anchor" href="#_9-适用法律与争议解决" aria-label="Permalink to &quot;**9. 适用法律与争议解决**&quot;">​</a></h2><p>​ 1. 本协议的订立、执行与解释及争议解决均适用中华人民共和国法律法规（不含冲突规范）。</p><p>​ 2. 因本协议引起的或与本协议有关的争议，双方应友好协商解决；协商不成的，任一方可向【合同履行地/运营主体所在地】有管辖权的人民法院提起诉讼。</p><h2 id="_10-联系我们" tabindex="-1"><strong>10. 联系我们</strong> <a class="header-anchor" href="#_10-联系我们" aria-label="Permalink to &quot;**10. 联系我们**&quot;">​</a></h2><p>如你对本协议有任何疑问、意见或建议，请通过以下方式与我们联系：</p><p>​ ● 运营主体：【考拉记账】</p><p>​ ● 联系邮箱：ruanweidev@163.com</p><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1>',40)])])}const u=e(n,[["render",p]]);export{c as __pageData,u as default};
